import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from rdkit import Chem
D=np.load('assembled.npz');p=D['xyz'];sym=D['symbols']
s='[C]1N(c2c(C(C)C)cccc2C(C)C)C=CN1c1c(C(C)C)cccc1C(C)C'
ms=[Chem.AddHs(Chem.MolFromSmiles(a)) for a in [s,s,'P(C)(C)C','[CH2]C']]
bonds=[];o=0
for m in ms:
 for b in m.GetBonds():bonds.append((o+b.GetBeginAtomIdx(),o+b.GetEndAtomIdx()))
 o+=m.GetNumAtoms()
bonds += [(150,0),(150,65),(150,130),(150,151),(150,152),(150,153),(150,154),(151,152),(151,143)]
print('Formula',dict(zip(*np.unique(sym,return_counts=True))))
for i,j in bonds:
 d=np.linalg.norm(p[i]-p[j])
 if (i>=150 or j>=150):print(i,j,sym[i],sym[j],round(d,3))
 if (i<150 and j<150 and d>1.99):print('LONG ORGANIC BOND',i,j,d)
# Short nonbonded contacts
bondset={tuple(sorted(b)) for b in bonds}
from collections import defaultdict
adj=defaultdict(set)
for i,j in bonds:adj[i].add(j);adj[j].add(i)
short=[]
for i in range(len(p)):
 for j in range(i):
  if (j,i) in bondset or adj[i]&adj[j]:continue
  d=np.linalg.norm(p[i]-p[j]);thr=1.5 if sym[i]=='H' and sym[j]=='H' else 1.85 if 'H' in [sym[i],sym[j]] else 2.3
  if d<thr:short.append((i,j,sym[i],sym[j],round(d,3)))
print('Short nonbonded',short)
colors={'C':'#444444','N':'blue','P':'orange','Ir':'purple','Zn':'#009b99','H':'#bbbbbb'}
fig=plt.figure(figsize=(12,7));ax=fig.add_subplot(111,projection='3d')
for i,j in bonds:
 ax.plot(*p[[i,j]].T,color='#aaaaaa' if 'H' in [sym[i],sym[j]] else '#444444',lw=.8 if 'H' in [sym[i],sym[j]] else 1.8)
for elem in colors:
 sel=sym==elem;ax.scatter(*p[sel].T,s=20 if elem=='H' else 130 if elem in ['Ir','Zn'] else 55,c=colors[elem],depthshade=True)
for i in [0,65,130,143,150,151,152,153,154]:ax.text(*p[i],f'{sym[i]}{i}',fontsize=9)
ax.set_box_aspect(np.ptp(p,axis=0));ax.view_init(elev=10,azim=-72);ax.set_xlabel('X');ax.set_ylabel('Y');ax.set_zlabel('Z');plt.tight_layout();plt.savefig('render.png',dpi=160)
